Date: Fri, 20 Nov 2026 23:48:27 +0100
Subject: [PATCH] libtaskmanager: keep launcher order when sorting
 alphabetically

With alphabetical sorting two launchers were sorted by row, and a
launcher whose window closes comes back as a new row at the end, so it
moved last. Sort launchers by launcher list position, then by row.

BUG: 528323
---
 libtaskmanager/tasksmodel.cpp | 12 +++++++++---
 1 file changed, 9 insertions(+), 3 deletions(-)

diff --git a/libtaskmanager/tasksmodel.cpp b/libtaskmanager/tasksmodel.cpp
index fd6246a363..d703e40b8c 100644
--- a/libtaskmanager/tasksmodel.cpp
+++ b/libtaskmanager/tasksmodel.cpp
@@ -738,13 +738,19 @@ bool TasksModel::Private::lessThan(const QModelIndex &left, const QModelIndex &r
         const bool leftIsLauncher = left.data(AbstractTasksModel::IsLauncher).toBool();
         const bool rightIsLauncher = right.data(AbstractTasksModel::IsLauncher).toBool();

+        const int leftPos = q->launcherPosition(left.data(AbstractTasksModel::LauncherUrlWithoutIcon).toUrl());
+        const int rightPos = q->launcherPosition(right.data(AbstractTasksModel::LauncherUrlWithoutIcon).toUrl());
+
+        // Sort launchers by their position in the launcher list, not by row: a launcher
+        // that was hidden by its window and comes back is re-inserted at the end.
         if (leftIsLauncher && rightIsLauncher) {
+            if (leftPos != rightPos) {
+                return (leftPos < rightPos);
+            }
+
             return (left.row() < right.row());
         }

-        const int leftPos = q->launcherPosition(left.data(AbstractTasksModel::LauncherUrlWithoutIcon).toUrl());
-        const int rightPos = q->launcherPosition(right.data(AbstractTasksModel::LauncherUrlWithoutIcon).toUrl());
-
         if (leftIsLauncher && !rightIsLauncher) {
             if (launchInPlace) {
                 if (rightPos != -1) {
